using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Mediator;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Mediator")]
    [TestClass]
    public class RJIT_CR_M_00009 : MediatorTestBase
    {
        [TestMethod]
        public void Response_Have_To_Be_Public()
        {
            var notPublicResponses = (from implementation in MediatorImplementations
                                      where implementation.Response != null
                                      where implementation.Response.Modifiers.Any(m => m != Modifier.Public)
                                      select new
                                      {
                                          Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FullQualifiedName:  {implementation.Handler.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Current:    

{implementation.Response.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Should be:  

{implementation.Response.SyntaxTree.Replace("private", "public")
                                   .Replace("internal", "public")
                                   .FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                      }).ToImmutableList();


            Assert.IsTrue(notPublicResponses.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MR_00009

Your MediatR response should be public. In real case scenarios your MediatR requests/response are an abstraction for your http requests.
The response is the result of your http request and have to be public because it is part of your API (public).

Found:{notPublicResponses.Count}

{notPublicResponses.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }
}
